#!/bin/sh
# SPDX-License-Identifier: LicenseRef-Vegan-Community-1.0
# The contracts at another PQZ parameter set (plan 5h Task 8d part 2; owner 2026-10-21: one set per build). Every PQZ
# contract reads its set from src/pqz/PqzSet.sol, generated by pqz-core/params/sets/gen_set.py; the committed one is
# n2304-kmax4096 (gen_set.py --check wants it). Since TODO 8g (4) (ARCH-POS-20) each set runs in its own fixed lane,
# scratchpad/lanes/<set>/, with the set installed there: the work tree's src/pqz/PqzSet.sol is never touched, `others`
# runs the sets in parallel, and --clean builds a lane from nothing (the round's final matrix, every pre-merge gate).
# Same CLI as before; everything is done by lanes.sh (its header: scopes, memory, logs, the mutants lane):
#   smartcontracts/evm/script/pqz/at-set.sh [--clean] <set|others> [sensitive|list|modules|forge args ...]
#   e.g. smartcontracts/evm/script/pqz/at-set.sh n2560-kmax16384 test --match-path 'test/pqz/*'
#        smartcontracts/evm/script/pqz/at-set.sh --clean others sensitive
# No outer scripts/capped is needed: each lane's forge takes its own slot (inside one, `others` runs one set at a time).
exec sh "$(dirname "$0")/lanes.sh" "$@"
